import{_ as t,o as e,c as r,a2 as a}from"./chunks/framework.BVc2lkLk.js";const g=JSON.parse('{"title":"配置 QQ 开放平台","description":"在面板里扫码创建或绑定 QQ 机器人，到 QQ 开放平台填写回调地址，把机器人拉进群并打开权限。","frontmatter":{"description":"在面板里扫码创建或绑定 QQ 机器人，到 QQ 开放平台填写回调地址，把机器人拉进群并打开权限。"},"headers":[],"relativePath":"deploy-qq.md","filePath":"deploy-qq.md","lastUpdated":1790607621000}'),l={name:"deploy-qq.md"};function s(i,o,n,p,c,d){return e(),r("div",null,[...o[0]||(o[0]=[a('<h1 id="配置-qq-开放平台" tabindex="-1">配置 QQ 开放平台 <a class="header-anchor" href="#配置-qq-开放平台" aria-label="Permalink to &quot;配置 QQ 开放平台&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>QQ 开放平台的界面偶尔会改版，下面的菜单名以 2026-09 为准。对不上时，找名字相近的菜单即可。</p></div><h2 id="_1-在面板里创建或绑定机器人" tabindex="-1">1. 在面板里创建或绑定机器人 <a class="header-anchor" href="#_1-在面板里创建或绑定机器人" aria-label="Permalink to &quot;1. 在面板里创建或绑定机器人&quot;">​</a></h2><p>引导部署不创建机器人，这一步在面板里做。用自定义域名打开面板，进入「设置」：</p><ul><li><strong>还没有机器人</strong>：点「扫码创建机器人」，用手机 QQ 扫码确认即可新建，AppID 与 AppSecret 自动保存。</li><li><strong>已有机器人</strong>：填入它的 AppID 与 AppSecret 并保存。保存前 Worker 会先向 QQ 验证一次。</li></ul><p><strong>必须先保存凭证再填回调地址</strong>：凭证没保存时 Worker 不会回应平台的校验请求，平台会报校验失败。</p><h2 id="_2-登录并找到机器人" tabindex="-1">2. 登录并找到机器人 <a class="header-anchor" href="#_2-登录并找到机器人" aria-label="Permalink to &quot;2. 登录并找到机器人&quot;">​</a></h2><p>打开 <a href="https://q.qq.com" target="_blank" rel="noreferrer">q.qq.com</a>，用手机 QQ 扫码登录，在应用管理里点进你的机器人。在面板里扫码新建的机器人也在这里。</p><p>进入 <strong>开发管理</strong>，核对这里的 AppID 和面板「设置」里的是否一致。</p><h2 id="_3-填写回调地址" tabindex="-1">3. 填写回调地址 <a class="header-anchor" href="#_3-填写回调地址" aria-label="Permalink to &quot;3. 填写回调地址&quot;">​</a></h2><ol><li>打开 <strong>回调配置</strong>（也可以直接访问 <a href="https://q.qq.com/qqbot/#/developer/webhook-setting" target="_blank" rel="noreferrer">https://q.qq.com/qqbot/#/developer/webhook-setting</a>）。</li><li>回调地址填面板概览页复制来的地址，即 <code>https://bot.example.com/webhook</code>。</li><li>在 <strong>添加事件</strong> 里全部勾选。没有插件处理的事件，框架会直接忽略，多勾没有坏处；少勾了对应的消息就收不到。</li><li>点确定保存。平台会立刻向这个地址发一次校验请求，没有提示“校验失败”就说明配好了。</li></ol><p>不需要配置 IP 白名单。</p><h2 id="_4-把机器人拉进群" tabindex="-1">4. 把机器人拉进群 <a class="header-anchor" href="#_4-把机器人拉进群" aria-label="Permalink to &quot;4. 把机器人拉进群&quot;">​</a></h2><p>回调地址校验通过后，就可以把机器人拉进<strong>你是群主或管理员</strong>的群：</p><ul><li><strong>群主</strong>：一定能拉进去。</li><li><strong>管理员</strong>：有时会拉不进去，规律还没摸清。拉不进去就换一个你是群主的群。</li></ul><p>机器人只能由它的主人拉进群，请别的群主代拉是不行的。</p><p>拉进群后，回到<a href="./deploy#_4-试一下">快速部署 · 试一下</a>，在群里 @机器人 发 <code>/sid</code>。</p><h2 id="_5-在群里打开权限" tabindex="-1">5. 在群里打开权限 <a class="header-anchor" href="#_5-在群里打开权限" aria-label="Permalink to &quot;5. 在群里打开权限&quot;">​</a></h2><p>机器人进群后默认只收得到 <strong>@ 它的消息</strong>，也不能主动发消息。需要的话，在群聊里点开机器人的头像，再点右上角进入权限配置：</p><ul><li><strong>获取群内全部消息</strong>：打开后，没 @ 机器人的消息也会推给它。插件的无前缀命令（<code>bare: true</code>）要靠这个权限。</li><li><strong>主动消息</strong>：打开后，机器人可以不等别人发言、自己往群里发消息，比如定时推送。</li></ul><p>这两个权限<strong>只有群主能打开</strong>。</p><h2 id="沙箱与发布上线-可选" tabindex="-1">沙箱与发布上线（可选） <a class="header-anchor" href="#沙箱与发布上线-可选" aria-label="Permalink to &quot;沙箱与发布上线（可选）&quot;">​</a></h2><p>平台上的 <strong>沙箱配置</strong> 和 <strong>发布流程</strong> 都不是必需的，个人使用可以跳过：</p><ul><li><strong>沙箱</strong>：比较老的机器人才有这项限制，只能在沙箱里添加的群和成员中使用。</li><li><strong>发布上线</strong>：让很多人都能添加这个机器人时才需要，在平台 <strong>首页</strong> 的 <strong>发布流程</strong> 提交审核。</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>目前只验证过个人使用。通过沙箱或发布上线给多人使用的场景还没有测试过。</p></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>保存回调地址时提示校验失败</strong></p><ul><li>填成了 <code>*.workers.dev</code> 的地址：QQ 访问不到，换成自定义域名。</li><li>域名刚绑上，证书或 DNS 还没生效：等几分钟，浏览器能打开面板后再保存。</li><li>面板里没有保存凭证，或者保存的 AppSecret 不是这个机器人的（比如在平台上重置过密钥）：到面板「设置」重新保存。</li><li>路径写错：应该是 <code>/webhook</code>。</li></ul><p><strong>校验通过了，但机器人没反应</strong></p><ul><li>事件没勾全：回到回调配置，把事件全部勾上。</li><li>群里没有 @机器人：群主没打开“获取群内全部消息”时，机器人只收得到 @ 它的消息，见<a href="#_5-在群里打开权限">在群里打开权限</a>。</li><li>较老的机器人：可能还受沙箱限制，见<a href="#沙箱与发布上线-可选">沙箱与发布上线</a>。</li><li>看面板概览页的「最近事件」（先点「开始实时调试」再发消息，马上就能看到）：有这条消息说明回调是通的，问题出在插件；完全没有记录说明平台没推过来，回头检查上面几条。</li></ul><p><strong>其他问题</strong></p><p>请到 GitHub <a href="https://github.com/QFlareBot/QFlareBot/issues" target="_blank" rel="noreferrer">提交 Issue</a>。</p>',32)])])}const q=t(l,[["render",s]]);export{g as __pageData,q as default};
